        assert_eq!(calls.len(), 1, "exactly one cleanup per invocation");
        assert_eq!(calls[0], vec!["1", "2", "3"], "keys from every page");
    }

    #[tokio::test]
    async fn multi_page_scope_does_not_self_delete() {
