//! Serde config types for the `partition:` block (#479).
//!
//! A partitioned row is fanned out into N independent invocations, each scoped
//! to one chunk of a range via `${partition.*}` tokens substituted into the
//! connector configs. This is `faucet backfill`'s window mechanism generalized:
//! from time-only to time / integer / offset, and from a separate bounded-replay
//! command to any run.
//!
//! ## Why the kinds are a tagged enum
//!
//! Each kind needs a different set of fields, and two of the mistakes are silent
//! data loss rather than errors:
//!
//! - `bounds` is meaningful for `integer` and required there, but meaningless for
//!   `offset`. As a tagged enum, serde makes it required exactly where it applies
//!   instead of a runtime "you must set this when kind is …" check.
//! - **A count is not a maximum key.** `{"total": 1234567}` equals the largest id
//!   only when ids are dense and 1-based; chunking an *id range* from a count
//!   silently stops early the moment ids are sparse (deletions, sharded id
//!   allocation, non-sequential keys), and every record above it is never
//!   fetched. Because `total` lives only on `offset` and `to` only on `integer`,
//!   that mistake is structurally impossible rather than merely documented.

use crate::chunking::Bounds;
use crate::error::{CliError, CliResult};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// A partitioned range. `kind` selects the variant.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum PartitionSpec {
    /// Split an integer range — the shape for an API or table filtered by an id
    /// range (`?id_from=&id_to=`, `WHERE id BETWEEN`).
    Integer {
        /// Inclusive lower bound.
        from: i64,
        /// Upper bound, interpreted per `bounds`.
        to: i64,
        /// Values per chunk. Must be > 0.
        chunk_size: u64,
        /// Whether `to` (and each chunk's `end`) is inclusive or exclusive.
        ///
        /// **Required, with no default.** Getting it wrong is silent: half-open
        /// chunks against an inclusive-bound source fetch one record twice per
        /// boundary; inclusive chunks against an exclusive source skip one per
        /// boundary. Neither raises.
        bounds: Bounds,
        /// Render the final chunk without an upper bound, so rows appended above
        /// `to` between planning and execution are still read. Costs nothing when
        /// the range is genuinely closed.
        #[serde(default)]
        to_unbounded: bool,
    },

    /// Split a time range — the same windowing `faucet backfill` uses, including
    /// its DST-correct calendar steps.
    Timestamp {
        /// RFC3339, or a bare date interpreted as midnight in `timezone`.
        from: String,
        /// Exclusive upper bound; time windows are always half-open.
        to: String,
        /// Window size: `45s`, `30m`, `6h`, `1d`, `1w`, or a bare integer =
        /// seconds. `d`/`w` are calendar steps, so `1d` and `24h` differ across a
        /// DST transition — deliberately.
        chunk_size: String,
        /// IANA timezone for date boundaries and calendar steps. Defaults to UTC.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        timezone: Option<String>,
    },

    /// Split a countable result set into offset/limit slices — the parallel form
    /// of what a source's serial offset pagination already does.
    Offset {
        /// Total rows in the result set.
        total: u64,
        /// Rows per chunk. Must be > 0.
        chunk_size: u64,
    },
}

impl PartitionSpec {
    /// Fail-fast validation, run by `faucet validate` and again before any run.
    /// Range/size errors surface from the planners; this covers what has to be
    /// checked before planning is even attempted.
    pub fn validate(&self) -> CliResult<()> {
        match self {
            Self::Integer { chunk_size, .. } | Self::Offset { chunk_size, .. } => {
                if *chunk_size == 0 {
                    // Deliberately unlike the `batch_size: 0` sentinel elsewhere,
                    // where 0 means "no batching" — here it would mean infinite
                    // chunks, so it is an error rather than a mode.
                    return Err(CliError::Config(
                        "partition.chunk_size must be greater than 0 (unlike `batch_size`, \
                         0 is not a 'no chunking' sentinel here)"
                            .into(),
                    ));
                }
            }
            Self::Timestamp {
                chunk_size,
                timezone,
                ..
            } => {
                crate::chunking::parse_window(chunk_size)?;
                if let Some(tz) = timezone {
                    tz.parse::<chrono_tz::Tz>().map_err(|_| {
                        CliError::Config(format!(
                            "'{tz}' is not a valid IANA timezone (e.g. UTC, America/New_York)"
                        ))
                    })?;
                }
            }
        }
        Ok(())
    }

    /// The token names this spec's chunks will define, for error messages that
    /// tell the user what they *can* reference.
    pub fn token_names(&self) -> &'static [&'static str] {
        match self {
            Self::Integer { .. } => &["start", "end", "index", "id"],
            Self::Timestamp { .. } => &[
                "start",
                "end",
                "start_date",
                "end_date",
                "start_unix",
                "end_unix",
                "index",
                "id",
            ],
            Self::Offset { .. } => &["offset", "limit", "index", "id"],
        }
    }

    /// Human label for logs and errors.
    pub fn kind_str(&self) -> &'static str {
        match self {
            Self::Integer { .. } => "integer",
            Self::Timestamp { .. } => "timestamp",
            Self::Offset { .. } => "offset",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(yaml: &str) -> Result<PartitionSpec, serde_yaml::Error> {
        serde_yaml::from_str(yaml)
    }

    #[test]
    fn integer_requires_bounds() {
        // The whole point of the tagged enum: omitting `bounds` on an integer
        // range is a parse error, not a runtime surprise at the first boundary.
        let err = parse("kind: integer\nfrom: 0\nto: 100\nchunk_size: 10\n")
            .expect_err("bounds must be required");
        assert!(err.to_string().contains("bounds"), "{err}");
    }

    #[test]
    fn integer_parses_with_bounds() {
        let s = parse("kind: integer\nfrom: 0\nto: 100\nchunk_size: 10\nbounds: inclusive\n")
            .unwrap();
        assert!(matches!(
            s,
            PartitionSpec::Integer {
                from: 0,
                to: 100,
                chunk_size: 10,
                bounds: Bounds::Inclusive,
                to_unbounded: false
            }
        ));
        s.validate().unwrap();
    }

    #[test]
    fn a_count_cannot_bound_an_id_range() {
        // `total` belongs to `offset` only. Chunking an id range from a count is
        // silently wrong when ids are sparse, so the shape forbids it.
        let err = parse("kind: integer\nfrom: 0\ntotal: 1000\nchunk_size: 10\nbounds: inclusive\n")
            .expect_err("total is not an integer-range field");
        assert!(err.to_string().contains("total"), "{err}");
    }

    #[test]
    fn an_id_bound_cannot_be_given_to_an_offset_range() {
        let err = parse("kind: offset\nto: 1000\nchunk_size: 10\n")
            .expect_err("to is not an offset field");
        assert!(err.to_string().contains("to"), "{err}");
    }

    #[test]
    fn offset_parses_and_needs_no_bounds() {
        let s = parse("kind: offset\ntotal: 250\nchunk_size: 100\n").unwrap();
        assert!(matches!(
            s,
            PartitionSpec::Offset {
                total: 250,
                chunk_size: 100
            }
        ));
        s.validate().unwrap();
    }

    #[test]
    fn timestamp_parses_and_validates_window_and_timezone() {
        let s = parse(
            "kind: timestamp\nfrom: 2026-01-01\nto: 2026-02-01\nchunk_size: 1d\n\
             timezone: America/New_York\n",
        )
        .unwrap();
        s.validate().unwrap();

        let bad_window = parse("kind: timestamp\nfrom: a\nto: b\nchunk_size: 1y\n").unwrap();
        assert!(bad_window.validate().is_err(), "1y is not a valid window");

        let bad_tz =
            parse("kind: timestamp\nfrom: a\nto: b\nchunk_size: 1d\ntimezone: Mars/Olympus\n")
                .unwrap();
        assert!(bad_tz.validate().is_err(), "bogus timezone must be rejected");
    }

    #[test]
    fn zero_chunk_size_is_rejected_with_the_batch_size_distinction_spelled_out() {
        let s = parse("kind: integer\nfrom: 0\nto: 10\nchunk_size: 0\nbounds: half_open\n").unwrap();
        let err = s.validate().unwrap_err();
        assert!(err.to_string().contains("greater than 0"), "{err}");
        assert!(
            err.to_string().contains("batch_size"),
            "the message should distinguish it from the batch_size sentinel: {err}"
        );
    }

    #[test]
    fn unknown_fields_are_rejected() {
        assert!(
            parse("kind: offset\ntotal: 10\nchunk_size: 5\nchunck_size: 5\n").is_err(),
            "a typo must not be silently ignored"
        );
    }

    #[test]
    fn token_names_match_the_kind() {
        let int = parse("kind: integer\nfrom: 0\nto: 1\nchunk_size: 1\nbounds: inclusive\n").unwrap();
        assert!(int.token_names().contains(&"start"));
        assert!(!int.token_names().contains(&"offset"));

        let off = parse("kind: offset\ntotal: 1\nchunk_size: 1\n").unwrap();
        assert!(off.token_names().contains(&"offset"));
        assert!(!off.token_names().contains(&"start"));
    }
}

//! Turn a [`PartitionSpec`](super::spec::PartitionSpec) into concrete chunks and
//! substitute their `${partition.*}` tokens into connector configs (#479).
//!
//! Substitution walks every string leaf of a config `Value`, exactly like
//! `backfill::plan::substitute_unit_tokens` — which is why this works for any
//! source without a line of connector code. A REST URL, a SQL `WHERE`, an object
//! prefix and a Mongo filter are all just strings.
//!
//! ## Injection
//!
//! Tokens land inside SQL and JSON strings, where `substitute_context` is
//! documented as unsafe. What makes it safe here is that every rendered value is
//! **faucet-generated and type-constrained** — an `i64`, a `u64`, or an RFC3339
//! timestamp formatted by chrono — never user data and never a passthrough of
//! anything a remote system said. [`render`] is the only place values are
//! produced, and it produces them from typed fields.

use super::spec::PartitionSpec;
use crate::chunking::{self, Bounds};
use crate::error::{CliError, CliResult};
use serde_json::Value;
use std::collections::BTreeMap;

/// The literal prefix a partition token starts with.
const PREFIX: &str = "${partition.";

/// One planned chunk: a stable id plus the tokens its invocation substitutes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PartitionChunk {
    /// Stable id, used as the state-key suffix and in log lines. Zero-padded so
    /// chunk ids sort in plan order.
    pub id: String,
    /// Token name → rendered value, e.g. `start` → `"10000"`.
    pub tokens: BTreeMap<String, String>,
    /// True for the final chunk of an `to_unbounded` integer range: its upper
    /// bound is omitted so late-arriving rows above the planned maximum are
    /// still read.
    pub open_ended: bool,
}

/// Plan every chunk for `spec`.
pub fn plan(spec: &PartitionSpec) -> CliResult<Vec<PartitionChunk>> {
    spec.validate()?;
    match spec {
        PartitionSpec::Integer {
            from,
            to,
            chunk_size,
            bounds,
            to_unbounded,
        } => {
            let chunks = chunking::plan_int_chunks(*from, *to, *chunk_size, *bounds)?;
            Ok(chunks
                .into_iter()
                .enumerate()
                .map(|(i, c)| {
                    let open = *to_unbounded && c.is_last;
                    let mut tokens = BTreeMap::new();
                    tokens.insert("start".into(), c.start.to_string());
                    tokens.insert("end".into(), c.end.to_string());
                    tokens.insert("index".into(), i.to_string());
                    tokens.insert("id".into(), c.id.clone());
                    PartitionChunk {
                        id: c.id,
                        tokens,
                        open_ended: open,
                    }
                })
                .collect())
        }

        PartitionSpec::Timestamp {
            from,
            to,
            chunk_size,
            timezone,
        } => {
            let tz: chrono_tz::Tz = timezone
                .as_deref()
                .unwrap_or("UTC")
                .parse()
                .map_err(|_| CliError::Config("invalid partition.timezone".into()))?;
            let step = chunking::parse_window(chunk_size)?;
            let from = chunking::parse_boundary(from, tz)?;
            let to = chunking::parse_boundary(to, tz)?;
            let chunks = chunking::plan_windows(from, to, Some(step), tz)?;
            Ok(chunks
                .into_iter()
                .enumerate()
                .map(|(i, c)| {
                    let mut tokens = BTreeMap::new();
                    tokens.insert("start".into(), c.start.to_rfc3339());
                    tokens.insert("end".into(), c.end.to_rfc3339());
                    tokens.insert("start_date".into(), c.start.format("%Y-%m-%d").to_string());
                    tokens.insert("end_date".into(), c.end.format("%Y-%m-%d").to_string());
                    tokens.insert("start_unix".into(), c.start.timestamp().to_string());
                    tokens.insert("end_unix".into(), c.end.timestamp().to_string());
                    tokens.insert("index".into(), i.to_string());
                    tokens.insert("id".into(), c.id.clone());
                    PartitionChunk {
                        id: c.id,
                        tokens,
                        open_ended: false,
                    }
                })
                .collect())
        }

        PartitionSpec::Offset { total, chunk_size } => {
            let chunks = chunking::plan_offset_chunks(*total, *chunk_size)?;
            Ok(chunks
                .into_iter()
                .enumerate()
                .map(|(i, c)| {
                    let mut tokens = BTreeMap::new();
                    tokens.insert("offset".into(), c.offset.to_string());
                    tokens.insert("limit".into(), c.limit.to_string());
                    tokens.insert("index".into(), i.to_string());
                    tokens.insert("id".into(), c.id.clone());
                    PartitionChunk {
                        id: c.id,
                        tokens,
                        open_ended: false,
                    }
                })
                .collect())
        }
    }
}

/// Substitute `${partition.*}` tokens in every string leaf of `value`.
///
/// An unrecognized token is a typo, not a passthrough: it errors, naming the
/// tokens this chunk actually defines. Silently leaving `${partition.strat}` in a
/// URL would send the literal text to the source.
pub fn substitute(value: &mut Value, chunk: &PartitionChunk) -> CliResult<()> {
    match value {
        Value::String(s) => {
            *s = substitute_in_str(s, chunk)?;
            Ok(())
        }
        Value::Array(a) => a.iter_mut().try_for_each(|v| substitute(v, chunk)),
        Value::Object(m) => m.values_mut().try_for_each(|v| substitute(v, chunk)),
        _ => Ok(()),
    }
}

fn substitute_in_str(input: &str, chunk: &PartitionChunk) -> CliResult<String> {
    let mut out = String::with_capacity(input.len());
    let mut rest = input;
    while let Some(pos) = rest.find(PREFIX) {
        out.push_str(&rest[..pos]);
        let after = &rest[pos + PREFIX.len()..];
        let close = after.find('}').ok_or_else(|| {
            CliError::Config(format!("unterminated ${{partition.…}} token in '{input}'"))
        })?;
        let token = &after[..close];
        let rendered = chunk.tokens.get(token).ok_or_else(|| {
            CliError::Config(format!(
                "unknown token ${{partition.{token}}} — this partition defines: {}",
                chunk.tokens.keys().cloned().collect::<Vec<_>>().join(", ")
            ))
        })?;
        out.push_str(rendered);
        rest = &after[close + 1..];
    }
    out.push_str(rest);
    Ok(out)
}

/// Whether a serialized config references any `${partition.*}` token.
///
/// A `partition:` block on a row whose source ignores the tokens would run the
/// same query N times, so this gates the config at load time.
pub fn references_partition(serialized: &str) -> bool {
    serialized.contains(PREFIX)
}

/// The `end` predicate for an open-ended final chunk is the caller's problem —
/// this reports whether one was planned so `expand` can require the config to
/// handle it.
pub fn has_open_ended(chunks: &[PartitionChunk]) -> bool {
    chunks.iter().any(|c| c.open_ended)
}

/// Bounds label for log lines.
pub fn bounds_label(b: Bounds) -> &'static str {
    match b {
        Bounds::Inclusive => "inclusive",
        Bounds::HalfOpen => "half_open",
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn int_spec(to_unbounded: bool) -> PartitionSpec {
        PartitionSpec::Integer {
            from: 0,
            to: 24,
            chunk_size: 10,
            bounds: Bounds::Inclusive,
            to_unbounded,
        }
    }

    #[test]
    fn integer_chunks_carry_start_end_index_id() {
        let chunks = plan(&int_spec(false)).unwrap();
        assert_eq!(chunks.len(), 3);
        assert_eq!(chunks[0].tokens["start"], "0");
        assert_eq!(chunks[0].tokens["end"], "9");
        assert_eq!(chunks[0].tokens["index"], "0");
        assert_eq!(chunks[2].tokens["end"], "24", "final chunk truncates at `to`");
        assert!(chunks.iter().all(|c| !c.open_ended));
    }

    #[test]
    fn only_the_final_chunk_is_open_ended_and_only_when_asked() {
        let chunks = plan(&int_spec(true)).unwrap();
        assert_eq!(chunks.iter().filter(|c| c.open_ended).count(), 1);
        assert!(chunks.last().unwrap().open_ended);
        assert!(has_open_ended(&chunks));
        assert!(!has_open_ended(&plan(&int_spec(false)).unwrap()));
    }

    #[test]
    fn offset_chunks_carry_offset_and_limit() {
        let chunks = plan(&PartitionSpec::Offset {
            total: 25,
            chunk_size: 10,
        })
        .unwrap();
        assert_eq!(chunks.len(), 3);
        assert_eq!(chunks[0].tokens["offset"], "0");
        assert_eq!(chunks[0].tokens["limit"], "10");
        assert_eq!(chunks[2].tokens["limit"], "5", "final limit is the remainder");
        assert!(!chunks[0].tokens.contains_key("start"), "no id-range tokens");
    }

    #[test]
    fn timestamp_chunks_carry_the_backfill_token_set() {
        let chunks = plan(&PartitionSpec::Timestamp {
            from: "2026-06-01".into(),
            to: "2026-06-04".into(),
            chunk_size: "1d".into(),
            timezone: None,
        })
        .unwrap();
        assert_eq!(chunks.len(), 3);
        for t in [
            "start",
            "end",
            "start_date",
            "end_date",
            "start_unix",
            "end_unix",
        ] {
            assert!(chunks[0].tokens.contains_key(t), "missing {t}");
        }
        assert_eq!(chunks[0].tokens["start_date"], "2026-06-01");
        assert_eq!(chunks[1].tokens["start_date"], "2026-06-02");
    }

    #[test]
    fn substitutes_into_nested_string_leaves_only() {
        let chunks = plan(&int_spec(false)).unwrap();
        let mut cfg = json!({
            "url": "https://api/x?from=${partition.start}&to=${partition.end}",
            "nested": { "list": ["chunk-${partition.index}", 7, true] },
            "count": 3
        });
        substitute(&mut cfg, &chunks[1]).unwrap();
        assert_eq!(cfg["url"], "https://api/x?from=10&to=19");
        assert_eq!(cfg["nested"]["list"][0], "chunk-1");
        assert_eq!(cfg["nested"]["list"][1], 7, "non-strings untouched");
        assert_eq!(cfg["count"], 3);
    }

    #[test]
    fn substitutes_the_same_token_more_than_once() {
        let chunks = plan(&int_spec(false)).unwrap();
        let mut cfg = json!({ "q": "id >= ${partition.start} AND ${partition.start} > 0" });
        substitute(&mut cfg, &chunks[0]).unwrap();
        assert_eq!(cfg["q"], "id >= 0 AND 0 > 0");
    }

    #[test]
    fn an_unknown_token_errors_and_lists_what_is_available() {
        let chunks = plan(&int_spec(false)).unwrap();
        let mut cfg = json!({ "url": "x?a=${partition.strat}" });
        let err = substitute(&mut cfg, &chunks[0]).unwrap_err().to_string();
        assert!(err.contains("strat"), "{err}");
        assert!(err.contains("start"), "should list the real tokens: {err}");
    }

    #[test]
    fn an_offset_config_cannot_reference_id_range_tokens() {
        // Guards the kind/token mismatch: a config written for an id range but
        // partitioned by offset fails loudly instead of sending literal text.
        let chunks = plan(&PartitionSpec::Offset {
            total: 10,
            chunk_size: 5,
        })
        .unwrap();
        let mut cfg = json!({ "url": "x?from=${partition.start}" });
        let err = substitute(&mut cfg, &chunks[0]).unwrap_err().to_string();
        assert!(err.contains("start"), "{err}");
        assert!(err.contains("offset"), "lists the offset tokens: {err}");
    }

    #[test]
    fn an_unterminated_token_is_a_typed_error() {
        let chunks = plan(&int_spec(false)).unwrap();
        let mut cfg = json!({ "url": "x?a=${partition.start" });
        let err = substitute(&mut cfg, &chunks[0]).unwrap_err().to_string();
        assert!(err.contains("unterminated"), "{err}");
    }

    #[test]
    fn detects_whether_a_config_references_the_tokens() {
        assert!(references_partition(r#"{"url":"x?a=${partition.start}"}"#));
        assert!(!references_partition(r#"{"url":"x?a=${now.date}"}"#));
    }

    #[test]
    fn rendered_values_are_numeric_or_rfc3339_never_passthrough() {
        // The injection-safety argument: every value comes from a typed field.
        let chunks = plan(&int_spec(false)).unwrap();
        for c in &chunks {
            for k in ["start", "end", "index"] {
                assert!(
                    c.tokens[k].parse::<i64>().is_ok(),
                    "{k} must render as an integer, got {:?}",
                    c.tokens[k]
                );
            }
        }
        let ts = plan(&PartitionSpec::Timestamp {
            from: "2026-06-01".into(),
            to: "2026-06-02".into(),
            chunk_size: "1d".into(),
            timezone: None,
        })
        .unwrap();
        assert!(chrono::DateTime::parse_from_rfc3339(&ts[0].tokens["start"]).is_ok());
    }
}

